+    fake.set_inbox(inbox);
+    let mut threads = HashMap::new();
+    for id in ["thr-1a", "thr-2b", "thr-3c", "thr-4d"] {
+        threads.insert(
+            id.to_string(),
+            thread(
+                id,
+                "hist-1000",
+                vec![msg(&format!("m-{id}"), "2026-01-01T10:00:00Z")],
